const emails = $('Build Email List').first().json.emails;
const raw = String($json.output || $json.text || '').replace(/```json/gi, '').replace(/```/g, '').trim();
const m = raw.match(/\{[\s\S]*\}/);
let picks;
try {
  const v = JSON.parse(m ? m[0] : raw);
  picks = Array.isArray(v.important) ? v.important : [];
} catch (e) {
  picks = emails.slice(0, 3).map(x => ({ n: x.n, reason: 'Could not rank, sent to be safe' }));
}
const clip = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length <= n ? s : s.slice(0, n) + '…'; };
const seenThreads = new Set();
const lines = [];
for (const p of picks) {
  const e = emails.find(x => x.n === Number(p.n));
  if (!e || seenThreads.has(e.threadId)) continue;
  seenThreads.add(e.threadId);
  lines.push((lines.length + 1) + '. ' + e.subject + '\n   From: ' + e.from + '\n   Why: ' + clip(p.reason, 120) + '\n   🔗 https://mail.google.com/mail/u/0/#all/' + e.threadId);
  if (lines.length >= 5) break;
}
const message = '📬 Important emails (' + lines.length + ')\n\n' + lines.join('\n\n');
return { json: { hasImportant: lines.length > 0, count: lines.length, message: message.slice(0, 3800) } };

const decode = s => String(s || '').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const clip = (s, n) => { s = decode(s).replace(/\s+/g, ' ').trim(); return s.length <= n ? s : s.slice(0, n) + '…'; };
const emails = $input.all().map((it, i) => {
  const j = it.json;
  return {
    n: i + 1,
    id: j.id,
    threadId: j.threadId || j.id,
    from: clip(j.From || '', 80),
    subject: clip(j.Subject || '(no subject)', 120),
    snippet: clip(j.snippet, 180)
  };
});
if (!emails.length) return [];
const emailList = emails.map(e => '#' + e.n + ' | From: ' + e.from + ' | Subject: ' + e.subject + ' | Preview: ' + e.snippet).join('\n');
return [{ json: { emails, emailList } }];
